1	use super::ip::*;
2	
3	// TODO: no_std alternatives
4	use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
5	
6	use spin::RwLock;
7	use treebitmap::address::Address;
8	use treebitmap::IpLookupTable;
9	use zerocopy::LayoutVerified;
10	
11	/* Functions for obtaining and validating "cryptokey" routes */
12	
13	pub struct RoutingTable<T: Eq + Clone> {
14	    ipv4: RwLock<IpLookupTable<Ipv4Addr, T>>,
15	    ipv6: RwLock<IpLookupTable<Ipv6Addr, T>>,
16	}
17	
18	impl<T: Eq + Clone> RoutingTable<T> {
19	    pub fn new() -> Self {
20	        RoutingTable {
21	            ipv4: RwLock::new(IpLookupTable::new()),
22	            ipv6: RwLock::new(IpLookupTable::new()),
23	        }
24	    }
25	
26	    // collect keys mapping to the given value
27	    fn collect<A>(table: &IpLookupTable<A, T>, value: &T) -> Vec<(A, u32)>
28	    where
29	        A: Address,
30	    {
31	        let mut res = Vec::new();
32	        for (ip, cidr, v) in table.iter() {
33	            if v == value {
34	                res.push((ip, cidr))
35	            }
36	        }
37	        res
38	    }
39	
40	    pub fn insert(&self, ip: IpAddr, cidr: u32, value: T) {
41	        match ip {
42	            IpAddr::V4(v4) => self.ipv4.write().insert(v4.mask(cidr), cidr, value),
43	            IpAddr::V6(v6) => self.ipv6.write().insert(v6.mask(cidr), cidr, value),
44	        };
45	    }
46	
47	    pub fn list(&self, value: &T) -> Vec<(IpAddr, u32)> {
48	        let mut res = vec![];
49	        res.extend(
50	            Self::collect(&*self.ipv4.read(), value)
51	                .into_iter()
52	                .map(|(ip, cidr)| (IpAddr::V4(ip), cidr)),
53	        );
54	        res.extend(
55	            Self::collect(&*self.ipv6.read(), value)
56	                .into_iter()
57	                .map(|(ip, cidr)| (IpAddr::V6(ip), cidr)),
58	        );
59	        res
60	    }
61	
62	    pub fn remove(&self, value: &T) {
63	        let mut v4 = self.ipv4.write();
64	        for (ip, cidr) in Self::collect(&*v4, value) {
65	            v4.remove(ip, cidr);
66	        }
67	
68	        let mut v6 = self.ipv6.write();
69	        for (ip, cidr) in Self::collect(&*v6, value) {
70	            v6.remove(ip, cidr);
71	        }
72	    }
73	
74	    #[inline(always)]
75	    pub fn get_route(&self, packet: &[u8]) -> Option<T> {
76	        match packet.get(0)? >> 4 {
77	            VERSION_IP4 => {
